    g.strokeStyle = 'rgba(168,85,247,0.8)'; g.lineWidth = 3;
    g.beginPath(); g.moveTo(0, s / 2 - 14); g.lineTo(s, s / 2 - 14); g.stroke();
    g.beginPath(); g.moveTo(0, s / 2 + 14); g.lineTo(s, s / 2 + 14); g.stroke();
  });
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  return t;
}
